&lt;li&gt;&lt;a href=&quot;#_die_6_epics_der_roadmap&quot;&gt;Die 6 EPICs der Roadmap&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_warum_funktioniert_es&quot;&gt;Warum funktioniert es?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_schlussfolgerung_das_fehlende_glied&quot;&gt;Schlussfolgerung : Das fehlende Glied&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_referenzen&quot;&gt;Referenzen&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;lesezeit: 8 minutes&lt;/div&gt;
&lt;p&gt;Vor zwei Wochen habe ich gestartet`capsule-gradle`— ein Plugin, das ein Deck transformiert reveal.js in WebM-Video-Kapsel mit TTS. Heute füge ich ein neues Plugin hinzu: &lt;code&gt;hyperframes-gradle&lt;/code&gt;. Es macht etwas, das capsule-gradle nicht tut: AsciiDoc &lt;strong&gt;direkt&lt;/strong&gt; in ein MP4-Video umwandeln, ohne reveal.js zu verwenden.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hier ist der Grund, warum dieses Plug-in existiert, wie es sich an das Bestehende anschließt, und was der HeyGen HyperFrames-Motor zur Content-Produktions-Pipeline bringt.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_das_loch_in_der_video_pipeline&quot;&gt;Das Loch in der Video-Pipeline&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Meine dokumentarische Pipeline produziert zwei Arten von Videos:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Wiederholungskapsel&lt;/strong&gt; (capsule-gradle) — ein reveal.js-Deck, das in WebM aufgezeichnet wurde, mit&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;narration TTS. Perfekt, um ein Modul zu wiederholen.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;animierte Folien&lt;/strong&gt; (slider-gradle) — ein interaktives reveal.js HTML Deck für&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;der Dozent vor Ort.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Aber es fehlt ein drittes Format: das &lt;strong&gt;vidéo standalone&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5565%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Use case&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Aktuelle Lösung&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Mangel&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Folien des Trainers&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;slider-gradle → reveal.js&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;�✅&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Kapsel Revision&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;capsule-gradle → WebM&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;✅&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Teaser-Video&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Keine&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;❌&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;animierte technische Demo&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;keine&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;❌&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;Dokument-zu-Video&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;keine&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;❌&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Der erste Use Case ist kritisch: Wie lässt sich automatisch generieren? ein Video von 60 Sekunden, das ein Projekt oder ein Modul vorstellt, mit GSAP-Animationen, Erzählung TTS und Hintergrundmusik – alles aus derselben AsciiDoc-Datei Und die Folien?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Capsule-gradle kann nicht antworten: Es muss bereits ein reveal.js-Deck haben. slider-gradle erzeugt dieses Deck gut, aber es ist nicht für das Videorendering konzipiert. Wir brauchten eine &lt;strong&gt;direkte&lt;/strong&gt; Pipeline: AsciiDoc → Video.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_hyperframes_der_motor&quot;&gt;HyperFrames : Der Motor&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ich habe entdeckthttps://github.com/heygen-com/hyperframes[HyperFrames] il y a einige Tage. Es ist ein Open-Source-Framework (Apache 2.0), das von HeyGen erstellt wurde, Das Einhorn der KI-Video. 22.700 Sterne auf GitHub. Der Pitch passt in ein Satz:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;quoteblock&quot;&gt;
&lt;blockquote&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;HTML schreiben. Video rendern. Für Agenten entwickelt.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/blockquote&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Das Prinzip: Sie schreiben HTML mit`data-*`attributes, Sie referenzieren eine GSAP-Animation (oder CSS, Lottie, Three.js…), und der Motor rendert alles als MP4 via Puppeteer (headless Chrome) + FFmpeg. Deterministisches Ergebnis: gleiche Eingabe, gleiche Frames, gleiches Video.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;div id=&quot;stage&quot; data-composition-id=&quot;intro&quot; data-start=&quot;0&quot; data-width=&quot;1920&quot; data-height=&quot;1080&quot;&amp;gt;
  &amp;lt;video class=&quot;clip&quot; data-start=&quot;0&quot; data-duration=&quot;6&quot; data-track-index=&quot;0&quot;
         src=&quot;background.mp4&quot; muted playsinline&amp;gt;&amp;lt;/video&amp;gt;

  &amp;lt;h1 id=&quot;title&quot; class=&quot;clip&quot; data-start=&quot;1&quot; data-duration=&quot;4&quot; data-track-index=&quot;1&quot;&amp;gt;
    Formation Docker &amp;amp; Kubernetes
  &amp;lt;/h1&amp;gt;

  &amp;lt;audio data-start=&quot;0&quot; data-duration=&quot;6&quot; data-track-index=&quot;2&quot;
         data-volume=&quot;0.3&quot; src=&quot;music.wav&quot;&amp;gt;&amp;lt;/audio&amp;gt;

  &amp;lt;script src=&quot;https://cdn.jsdelivr.net/npm/gsap@3/dist/gsap.min.js&quot;&amp;gt;&amp;lt;/script&amp;gt;
  &amp;lt;script&amp;gt;
    const tl = gsap.timeline({ paused: true });
    tl.from(&quot;#title&quot;, { opacity: 0, y: 40, duration: 0.8 }, 1);
    window.__timelines = window.__timelines || {};
    window.__timelines.intro = tl;
  &amp;lt;/script&amp;gt;
&amp;lt;/div&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Was macht HyperFrames anders als Remotion? Kein React, kein Bundler, kein JSX. Rohes HTML, das KI-Agenten nativ schreiben können. Es ist &lt;strong&gt;exakt&lt;/strong&gt; für meine Pipeline zugeschnitten: planner-gradle mit deepseek kann dieses HTML aus einem SPG/SPD-Plan erzeugen, und ein Gradle-Plugin kann es in MP4 konvertieren.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_die_architektur_des_plugins&quot;&gt;Die Architektur des Plugins&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;hyperframes-gradle folgt dem gleichen Muster wie alle meine Plugins: der &lt;a href=&quot;0124_architecture_plugin_gradle_racine_consommateur_independant_post.html&quot;&gt;Muster « Plugin Unabhängig + Konsumenten-Wurzel »&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;hyperframes-gradle/
├── settings.gradle.kts          ← racine consommateur (dogfood)
├── build.gradle.kts              ← 3 lignes : apply plugin hyperframes
├── hyperframes-plugin/           ← BUILD INDÉPENDANT
│   ├── gradlew                    ← son propre wrapper
│   ├── build.gradle.kts           ← java-gradle-plugin
│   ├── src/main/kotlin/education/cccp/hyperframes/
│   │   ├── HyperframesPlugin.kt
│   │   ├── GenerateHyperframesHtmlTask.kt
│   │   ├── RenderHyperframesTask.kt
│   │   └── HyperframesExtension.kt
│   ├── .agents/                   ← gouvernance agent
│   └── doc/
│       └── HYPERFRAMES_ARCHITECTURE.adoc
└── video.yml                      ← configuration dogfood&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_die_pipeline_in_vier_schritten&quot;&gt;Die Pipeline in vier Schritten&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 8) ]

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 11

title Pipeline hyperframes-gradle

rectangle &quot;AsciiDoc
Quelle&quot; as adoc #LightYellow
^^^^^
 Syntax Error? (Assumed diagram type: activity)

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 11

title Pipeline hyperframes-gradle

rectangle &quot;AsciiDoc
Quelle&quot; as adoc #LightYellow
rectangle &quot;AsciidoctorJ&quot; as asciidoctorj #LightBlue
rectangle &quot;HTML HyperFrames\n(data-* Attribute)&quot; as html #LightGreen
rectangle &quot;HyperFrames CLI\n(Node.js 22+)&quot; as cli #Lavender
rectangle &quot;video.mp4&quot; as mp4 #Gold

adoc -right-&amp;gt; asciidoctorj : parse blocs customs
asciidoctorj -right-&amp;gt; html : génère HTML
html -right-&amp;gt; cli : ProcessBuilder\nnpx hyperframes render
cli -right-&amp;gt; mp4 : Puppeteer + FFmpeg
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;AsciidoctorJ&lt;/strong&gt; analysiert den AsciiDoc-Quellcode und extrahiert die benutzerdefinierten Blöcke&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;[hyperframes-composition]&lt;/code&gt;, &lt;code&gt;[hyperframes-track]&lt;/code&gt;, &lt;code&gt;[hyperframes-animation]&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;GenerateHyperframesHtmlTask&lt;/strong&gt; generiert den HyperFrames-HTML mit dem&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`data-*`entsprechende Attribute.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;RenderHyperframesTask&lt;/strong&gt; ruft die HyperFrames-CLI über`ProcessBuilder`:&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;npx hyperframes render --input index.html --output video.mp4&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;MP4 wird bereitgestellt in`output/`mit einem`metadata.json`für die Orchestrierung.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_die_dsl_asciidoc&quot;&gt;Die DSL AsciiDoc&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Der wirkliche Mehrwert des Plugins ist das AsciiDoc‑DSL. Der Benutzer Er schreibt niemals HTML. Er annotiert sein bestehendes AsciiDoc-Dokument :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Formation Docker &amp;amp; Kubernetes
:hyperframes-width: 1920
:hyperframes-height: 1080
:hyperframes-fps: 30

[hyperframes-composition, id=&quot;intro&quot;]
== Introduction

Le titre apparaît avec un fondu GSAP sur fond vidéo.

[hyperframes-track, index=0, start=0, duration=6]
video::assets/background.mp4[muted, playsinline]

[hyperframes-track, index=1, start=1, duration=4]
Formation Docker &amp;amp; Kubernetes

[hyperframes-animation, type=gsap]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;const tl = gsap.timeline({ paused: true }); tl.from(&quot;#title&quot;, { opacity: 0, y: 40, duration: 0.8 }, 1); window.&lt;em&gt;timelines = window.&lt;/em&gt;timelines || {}; window.__timelines.intro = tl;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Die docinfo-Attribute (&lt;code&gt;:hyperframes-width:&lt;/code&gt;) legen die Dimensionen fest. Die benutzerdefinierten Blöcke definieren die Kompositionen und die Spuren. Der Block `[hyperframes-animation]`enthält den rohen GSAP-Code — dass der KI-Agent kann aus einer Beschreibung in natürlicher Sprache generieren.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_die_bridge_node_js&quot;&gt;Die Bridge Node.js&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Der einzige technische Reibungspunkt: HyperFrames ist in Node.js/TypeScript, und meine Plugins sind in Kotlin/JVM. Die Lösung ist ein`ProcessBuilder`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Note: The output preserves the exact spacing and punctuation as provided. No translation is needed for punctuation.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class RenderHyperframesTask : DefaultTask() {

    @TaskAction
    fun render() {
        val process = ProcessBuilder(
            &quot;npx&quot;, &quot;hyperframes&quot;, &quot;render&quot;,
            &quot;--input&quot;, inputHtml.absolutePath,
            &quot;--output&quot;, outputMp4.absolutePath
        )
            .inheritIO()
            .start()

        val exitCode = process.waitFor()
        require(exitCode == 0) {
            &quot;HyperFrames render failed with exit code $exitCode&quot;
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Keine Kopplung JVM-Code ↔ Node.js. Der Vertrag erfolgt über die Kommandozeile. und Dateien auf der Festplatte. Das ist das gleiche Muster wie`plantuml-gradle` (die die PlantUML-CLI aufruft) oder`slider-gradle`(der AsciidoctorJ aufruft) Nichts Neues unter der Sonne — nur auf ein neueres Werkzeug angewendet.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zwei_video_plugins_zwei_nutzungen&quot;&gt;Zwei Video-Plugins, Zwei Nutzungen&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
&lt;col style=&quot;width: 4.7619%;&quot;&gt;
