&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_die_abhängigkeit_window_firebase&quot;&gt;Die Abhängigkeit `window.&lt;em&gt;FIREBASE&lt;/em&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_der_neue_contact_js&quot;&gt;Der neue `contact.js&lt;/a&gt;&lt;/li&gt;
