&lt;li&gt;&lt;a href=&quot;#_zusammenfassung_der_änderungen&quot;&gt;Zusammenfassung der Änderungen&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_nächste_schritte_backlog&quot;&gt;Nächste Schritte (backlog)&lt;/a&gt;&lt;/li&gt;
