left to right direction

rectangle &quot;AGENT.adoc
(Wurzel — EAGER)&quot; as AGENT #E3F2FD {
  rectangle &quot;�📖 **Narratives Format**
Das Storytelling der Regel
die gelernte Lektion, der Kontext&quot; as NARR
  rectangle &quot;🏗️ **Vollständige Architektur**
Projektstruktur, Komponenten
Detaillierter Backlog US&quot; as ARCHI
  rectangle &quot;📋 **Erklärende Regeln**
Warum existiert die Regel?
Verlauf des Vorfalls&quot; as EXPL
}

rectangle &quot;INDEX.adoc\n(.agents/ — EAGER)&quot; as INDEX #E8F5E9 {
  rectangle &quot;⚡ **Ausführendes Format**
Die nackte Regel, ohne Begründung
Schnelle Konsultation&quot; as EXEC
  rectangle &quot;�📊 **Roadmap &amp;amp; EPICs**\nZusammenfassungstabelle\nFortschritt, Score, Priorität&quot; as ROAD
