 Syntax Error? (Assumed diagram type: sequence)

@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Entwickler
oder cron&quot; as dev
participant &quot;vscode-update.sh&quot; as script
participant &quot;VS-Code-Tarball
(code.visualstudio.com)&quot; as remote
participant &quot;~/apps/
VSCode-linux-x64&quot; as local
