&lt;li&gt;&lt;a href=&quot;#_eine_jdk_version_installieren&quot;&gt;&lt;strong&gt;Eine JDK-Version installieren&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_installation_überprüfen&quot;&gt;Installation überprüfen&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_die_ide_intellij_idea&quot;&gt;2. Die IDE : IntelliJ IDEA&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_gradle_das_build_tool&quot;&gt;3. Gradle: Das Build-Tool&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_installation_über_sdkman&quot;&gt;Installation über SDKMAN!&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_gradle_installieren&quot;&gt;Gradle installieren&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_installation_überprüfen_2&quot;&gt;Installation überprüfen&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_jbake_der_statische_seiten_generator&quot;&gt;4. JBake : Der statische Seiten-Generator&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_installation_über_sdkman_2&quot;&gt;Installation über SDKMAN!&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_jbake_installieren&quot;&gt;JBake installieren&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_installation_überprüfen_3&quot;&gt;&lt;strong&gt;Installation überprüfen&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_der_gradle_wrapper_die_absolut_beste_praxis&quot;&gt;5. Der Gradle Wrapper: Die absolut beste Praxis&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_6_docker_und_portainer_für_reproduzierbare_builds_optional&quot;&gt;6. Docker und Portainer: Für reproduzierbare Builds (Optional)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_installation_von_docker_engine&quot;&gt;Installation von Docker Engine&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_docker_über_das_offizielle_skript_installieren&quot;&gt;&lt;strong&gt;Docker über das offizielle Skript installieren :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_docker_ohne_sudo_verwalten_empfohlen&quot;&gt;Docker ohne &lt;code&gt;sudo&lt;/code&gt; verwalten (empfohlen):&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_docker_mit_portainer_gui_verwalten&quot;&gt;Docker mit Portainer (GUI) verwalten&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ein_volume_für_die_daten_von_portainer&quot;&gt;Ein Volume für die Daten von Portainer :&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_portainer_container_starten&quot;&gt;Portainer-Container starten :&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
