&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_objekte_und_modelle_der_pipeline&quot;&gt;Objekte und Modelle der Pipeline&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_klassendiagramm_cicd_modelle&quot;&gt;Klassendiagramm - CI/CD-Modelle&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/diag-plantuml-md5-8e577c6775af500a61e19e4e57d61499.png&quot; alt=&quot;Diagram&quot; width=&quot;814&quot; height=&quot;635&quot;&gt;
