&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_konfiguration_der_geheimnisse&quot;&gt;Konfiguration der Geheimnisse&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Damit die Pipeline funktioniert, müssen Sie die folgenden Geheimnisse in GitHub konfigurieren:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_geheimnisse_github_actions&quot;&gt;Geheimnisse GitHub Actions&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;bash&quot;&gt;# Dans Settings &amp;gt; Secrets and variables &amp;gt; Actions

# Token PyPI pour la production
PYPI_API_TOKEN=pypi-...

# Token Test PyPI pour les pré-releases
TEST_PYPI_API_TOKEN=pypi-...

# Token GitHub pour créer les releases
GITHUB_TOKEN=(automatiquement fourni)

# Token Codecov (optionnel)
CODECOV_TOKEN=...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_generierung_der_pypi_tokens&quot;&gt;Generierung der PyPI-Tokens&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;bash&quot;&gt;# 1. Créer un compte sur PyPI et Test PyPI
# 2. Aller dans Account Settings &amp;gt; API tokens
# 3. Créer un token avec scope &quot;Entire account&quot; ou spécifique au projet
# 4. Format du token : pypi-AgEIcHlwaS5vcmc...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_lokale_entwicklungs_skripte&quot;&gt;Lokale Entwicklungs-Skripte&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Um die Entwicklung zu erleichtern, erstellen Sie Hilfsskripte:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_makefile&quot;&gt;Makefile&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;makefile&quot;&gt;.PHONY: install test lint format security build clean release-test release-prod

install:
	pip install -e &quot;.[dev]&quot;

test:
	pytest tests/ -v --cov=src/playlist_downloader

lint:
	flake8 src tests
	mypy src

format:
	black src tests

security:
	bandit -r src/
	safety check

build:
	python -m build
	twine check dist/*

clean:
	rm -rf build/ dist/ *.egg-info/
	find . -type d -name __pycache__ -delete
	find . -name &quot;*.pyc&quot; -delete

release-test: clean build
	twine upload --repository testpypi dist/*

release-prod: clean build
	twine upload dist/*

pre-commit: format lint test security
	@echo &quot;✅ Prêt pour commit&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_versionsskript&quot;&gt;Versionsskript&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;python&quot;&gt;#!/usr/bin/env python3
&quot;&quot;&quot;Script pour gérer les versions du projet.&quot;&quot;&quot;

import sys
import subprocess
from pathlib import Path

def get_current_version():
    &quot;&quot;&quot;Récupère la version actuelle depuis git.&quot;&quot;&quot;
    try:
        result = subprocess.run(
            [&quot;git&quot;, &quot;describe&quot;, &quot;--tags&quot;, &quot;--abbrev=0&quot;],
            capture_output=True,
            text=True,
            check=True
        )
        return result.stdout.strip()
    except subprocess.CalledProcessError:
        return &quot;0.0.0&quot;

def create_version_tag(version, message=None):
    &quot;&quot;&quot;Crée un tag de version.&quot;&quot;&quot;
    if not version.startswith(&#39;v&#39;):
        version = f&#39;v{version}&#39;

    tag_message = message or f&quot;Release {version}&quot;

    subprocess.run([&quot;git&quot;, &quot;tag&quot;, &quot;-a&quot;, version, &quot;-m&quot;, tag_message], check=True)
    print(f&quot;✅ Tag {version} créé&quot;)

    # Push le tag
    subprocess.run([&quot;git&quot;, &quot;push&quot;, &quot;origin&quot;, version], check=True)
    print(f&quot;✅ Tag {version} poussé vers origin&quot;)

if __name__ == &quot;__main__&quot;:
    if len(sys.argv) &amp;lt; 2:
        current = get_current_version()
        print(f&quot;Version actuelle: {current}&quot;)
        print(&quot;Usage: python version.py &amp;lt;new_version&amp;gt; [message]&quot;)
        sys.exit(1)

    new_version = sys.argv[1]
    message = sys.argv[2] if len(sys.argv) &amp;gt; 2 else None

    create_version_tag(new_version, message)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_gute_praktiken_und_empfehlungen&quot;&gt;Gute Praktiken und Empfehlungen&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_semantisches_versioning&quot;&gt;Semantisches Versioning&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Verwenden Sie die semantische Versionierung (SemVer):&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MAJOR.MINOR.PATCH&lt;/code&gt; (ex: 1.2.3)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;`MAJOR`inkompatible Änderungen&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MINOR&lt;/code&gt;: neue kompatible Funktionen&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;`PATCH`kompatible Fehlerbehebungen&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_branching_strategie&quot;&gt;Branching-Strategie&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;text&quot;&gt;main          ──●──●──●──●──●────●── (releases stables)
               /       /          /
develop    ──●──●──●──●──●──●──●──●── (développement)
            /     /        /
feature/xxx  ●──●──●──●──●──/ (fonctionnalités)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tests_und_abdeckung&quot;&gt;Tests und Abdeckung&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Minimale Codeabdeckung: 85%&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Einheitstests für die Geschäftslogik&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Integrations-Tests für die Adapter&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;End-to-End-Tests für die CLI&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sicherheit&quot;&gt;Sicherheit&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Automatischer Abhängigkeitsscan (Safety)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Statische Codeanalyse (Bandit)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Geheimnisse nie im Code&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Verwendung von spezifischen PyPI-Token&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_monitoring_und_observabilität&quot;&gt;Monitoring und Observabilität&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pipeline_metriken&quot;&gt;Pipeline-Metriken&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;# .github/workflows/metrics.yml
name: Pipeline Metrics

on:
  workflow_run:
    workflows: [&quot;CI&quot;, &quot;Release&quot;]
    types: [completed]

jobs:
  metrics:
    runs-on: ubuntu-latest
    steps:
    - name: Collect metrics
      run: |
        echo &quot;Pipeline: ${{ github.event.workflow_run.name }}&quot;
        echo &quot;Status: ${{ github.event.workflow_run.conclusion }}&quot;
        echo &quot;Duration: ${{ github.event.workflow_run.updated_at - github.event.workflow_run.created_at }}&quot;
        # Envoyer vers système de monitoring&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_benachrichtigungen&quot;&gt;Benachrichtigungen&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;# Ajout dans les workflows pour notifications
- name: Notify on failure
  if: failure()
  uses: 8398a7/action-slack@v3
  with:
    status: failure
    text: &quot;❌ Pipeline failed for ${{ github.repository }}&quot;
  env:
    SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK }}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_fazit&quot;&gt;Fazit&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dieser vollständige CI/CD-Pipeline für Python bietet:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;vollständige Automatisierung&lt;/strong&gt;: von der Validierung des Codes zur Veröffentlichung&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Sicherheit&lt;/strong&gt;: automatische Scans und sichere Verwaltung der Geheimnisse&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Qualität&lt;/strong&gt;: Tests mehrerer Versionen, Linting und Codeabdeckung&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Zuverlässigkeit&lt;/strong&gt;: schrittweise Bereitstellung über Test PyPI&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Nachverfolgbarkeit&lt;/strong&gt;: artifacts, Berichte und releases GitHub&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Die Annahme dieser Praktiken gewährleistet einen robusten und professionellen Bereitstellungsprozess für Ihre Python-CLI-Anwendungen, wodurch die Wartung und Weiterentwicklung Ihrer Projekte langfristig erleichtert wird.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
