&lt;li&gt;&lt;a href=&quot;#_gui_option_psensor&quot;&gt;GUI-Option : `psensor&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_zusätzliche_tipps&quot;&gt;Zusätzliche Tipps&lt;/a&gt;&lt;/li&gt;
