&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_einführung&quot;&gt;Einführung&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Zielgruppe :&lt;/em&gt; Kotlin-Entwickler von mittlerem bis fortgeschrittenem Niveau.&lt;/div&gt;
&lt;p&gt;In der Welt der funktionalen Programmierung in Kotlin bietet die Arrow-Bibliothek leistungsstarke Werkzeuge zur Behandlung von Fehlern und alternativen Fällen. Unter diesen Werkzeugen ist die Monade`Either`zeichnet sich dadurch aus, dass es zwei mögliche Zustände darstellen kann: Erfolg (Right) oder Fehler (Left). Aber wie kann man effizient zwischen diesen beiden Zuständen navigieren? Das werden wir in diesem Artikel untersuchen.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_was_ist_die_either_monade&quot;&gt;Was ist die Either-Monade?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Die Monade`Either`ist eine Datenstruktur, die zwei sich gegenseitig ausschließende Möglichkeiten repräsentiert. In Kotlin mit Arrow wird sie häufig verwendet, um die Erfolgs- und Fehlerfälle einer Operation zu behandeln, wobei sie eine elegante Alternative zu traditionellen Ausnahmen bietet.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_warum_either_verwenden&quot;&gt;Warum Either verwenden?&lt;/h3&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Explizite Fehlerbehandlung: Zwingt den Entwickler, Fehlersituationen zu berücksichtigen.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Funktionale Komposition: Erleichtert das Verketten von Operationen, die fehlschlagen können.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Typsicherheit: Fehler sind typisiert, was hilft, sie präziser zu handhaben.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Keine Ausnahmen: Vermeide Nebeneffekte und unerwartete Unterbrechungen des Ausführungsflusses.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kontext&quot;&gt;Kontext&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Stellen Sie sich vor, Sie entwickeln eine REST-API mithttps://spring.io/projects/spring-boot/[Spring Boot,windows=später-lesen] et &lt;a href=&quot;https://kotlinlang.org/&quot;&gt;Kotlin&lt;/a&gt;, indem die Bibliothek verwendet wirdhttps://arrow-kt.io/[Pfeil,Fenster=read-later]. Sie haben eine Funktion`findOneUserByEmail`der ein zurückgibt`Either&amp;lt;Throwable, User&amp;gt;`. Wie können Sie dieses Ergebnis elegant und funktional behandeln?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Wir haben eine Klasse User:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;@file:Suppress(
    &quot;RemoveRedundantQualifierName&quot;,
    &quot;MemberVisibilityCanBePrivate&quot;,
    &quot;SqlNoDataSourceInspection&quot;
)

package webapp.users

import arrow.core.Either
import arrow.core.left
import arrow.core.right
import com.fasterxml.jackson.annotation.JsonIgnore
import com.fasterxml.jackson.databind.ObjectMapper
import jakarta.validation.constraints.NotNull
import jakarta.validation.constraints.Pattern
import jakarta.validation.constraints.Size
import org.springframework.beans.factory.getBean
import org.springframework.context.ApplicationContext
import org.springframework.data.r2dbc.core.R2dbcEntityTemplate
import org.springframework.r2dbc.core.DatabaseClient
import org.springframework.r2dbc.core.awaitOne
import org.springframework.r2dbc.core.awaitRowsUpdated
import webapp.core.property.ANONYMOUS_USER
import webapp.core.property.EMPTY_STRING
import webapp.core.utils.AppUtils.cleanField
import webapp.users.EntityModel.Companion.ID_MEMBER
import webapp.users.User.UserDao.Attributes.EMAIL_ATTR
import webapp.users.User.UserDao.Attributes.ID_ATTR
import webapp.users.User.UserDao.Attributes.LANG_KEY_ATTR
import webapp.users.User.UserDao.Attributes.LOGIN_ATTR
import webapp.users.User.UserDao.Attributes.PASSWORD_ATTR
import webapp.users.User.UserDao.Attributes.VERSION_ATTR
import webapp.users.User.UserDao.Constraints.LOGIN_REGEX
import webapp.users.User.UserDao.Fields.EMAIL_FIELD
import webapp.users.User.UserDao.Fields.ID_FIELD
import webapp.users.User.UserDao.Fields.LANG_KEY_FIELD
import webapp.users.User.UserDao.Fields.LOGIN_FIELD
import webapp.users.User.UserDao.Fields.PASSWORD_FIELD
import webapp.users.User.UserDao.Fields.VERSION_FIELD
import webapp.users.User.UserDao.Relations.INSERT
import webapp.users.security.Role
import webapp.users.security.Role.RoleDao
import webapp.users.security.UserRole.UserRoleDao
import java.util.*
import jakarta.validation.constraints.Email as EmailConstraint

data class User(
    override val id: UUID? = null,

    @field:NotNull
    @field:Pattern(regexp = LOGIN_REGEX)
    @field:Size(min = 1, max = 50)
    val login: String,

    @JsonIgnore
    @field:NotNull
    @field:Size(min = 60, max = 60)
    val password: String = EMPTY_STRING,

    @field:EmailConstraint
    @field:Size(min = 5, max = 254)
    val email: String = EMPTY_STRING,

    @JsonIgnore
    val roles: MutableSet&amp;lt;Role&amp;gt; = mutableSetOf(Role(ANONYMOUS_USER)),

    @field:Size(min = 2, max = 10)
    val langKey: String = EMPTY_STRING,

    @JsonIgnore
    val version: Long = -1,
) : EntityModel&amp;lt;UUID&amp;gt;() {

    companion object {
        @JvmStatic
        fun main(args: Array&amp;lt;String&amp;gt;) = println(UserDao.Relations.sqlScript)
    }

    object UserDao {
        object Constraints {
            // Regex for acceptable logins
            const val LOGIN_REGEX =
                &quot;^(?&amp;gt;[a-zA-Z0-9!$&amp;amp;*+=?^_`{|}~.-]+@[a-zA-Z0-9-]+(?:\\.[a-zA-Z0-9-]+)*)|(?&amp;gt;[_.@A-Za-z0-9-]+)$&quot;
            const val PASSWORD_MIN: Int = 4
            const val PASSWORD_MAX: Int = 16
            const val IMAGE_URL_DEFAULT = &quot;https://placehold.it/50x50&quot;
            const val PHONE_REGEX = &quot;^(\\+|00)?[1-9]\\d{0,49}\$&quot;
        }

        object Members {
            const val PASSWORD_MEMBER = &quot;password&quot;
            const val ROLES_MEMBER = &quot;roles&quot;
        }

        object Fields {
            const val ID_FIELD = &quot;`id`&quot;
            const val LOGIN_FIELD = &quot;`login`&quot;
            const val PASSWORD_FIELD = &quot;`password`&quot;
            const val EMAIL_FIELD = &quot;`email`&quot;
            const val LANG_KEY_FIELD = &quot;`lang_key`&quot;
            const val VERSION_FIELD = &quot;`version`&quot;
        }

        object Attributes {
            val ID_ATTR = ID_FIELD.cleanField()
            val LOGIN_ATTR = LOGIN_FIELD.cleanField()
            val PASSWORD_ATTR = PASSWORD_FIELD.cleanField()
            val EMAIL_ATTR = EMAIL_FIELD.cleanField()
            const val LANG_KEY_ATTR = &quot;langKey&quot;
            val VERSION_ATTR = VERSION_FIELD.cleanField()
        }

        object Relations {
            const val TABLE_NAME = &quot;`user`&quot;
            const val SQL_SCRIPT = &quot;&quot;&quot;
            CREATE TABLE IF NOT EXISTS $TABLE_NAME (
                $ID_FIELD                     UUID default random_uuid() PRIMARY KEY,
                $LOGIN_FIELD                  VARCHAR,
                $PASSWORD_FIELD               VARCHAR,
                $EMAIL_FIELD                  VARCHAR,
                $LANG_KEY_FIELD               VARCHAR,
                $VERSION_FIELD                bigint
            );
            CREATE UNIQUE INDEX IF NOT EXISTS `uniq_idx_user_login`
            ON $TABLE_NAME ($LOGIN_FIELD);
            CREATE UNIQUE INDEX IF NOT EXISTS `uniq_idx_user_email`
            ON $TABLE_NAME ($EMAIL_FIELD);
&quot;&quot;&quot;

            @Suppress(&quot;SqlDialectInspection&quot;)
            const val INSERT = &quot;&quot;&quot;
            insert into $TABLE_NAME (
                $LOGIN_FIELD, $EMAIL_FIELD,
                $PASSWORD_FIELD, $LANG_KEY_FIELD,
                $VERSION_FIELD
            ) values ( :login, :email, :password, :langKey, :version)&quot;&quot;&quot;

            @JvmStatic
            val sqlScript: String
                get() = setOf(
                    UserDao.Relations.SQL_SCRIPT,
                    RoleDao.Relations.SQL_SCRIPT,
                    UserRoleDao.Relations.SQL_SCRIPT
                ).joinToString(&quot;&quot;)
                    .trimMargin()
        }

        object Dao {
            val Pair&amp;lt;User, ApplicationContext&amp;gt;.toJson: String
                get() = second.getBean&amp;lt;ObjectMapper&amp;gt;().writeValueAsString(first)

            suspend fun Pair&amp;lt;User, ApplicationContext&amp;gt;.save(): Either&amp;lt;Throwable, Long&amp;gt; = try {
                second.getBean&amp;lt;R2dbcEntityTemplate&amp;gt;()
                    .databaseClient
                    .sql(INSERT)
                    .bind(LOGIN_ATTR, first.login)
                    .bind(EMAIL_ATTR, first.email)
                    .bind(PASSWORD_ATTR, first.password)
                    .bind(LANG_KEY_ATTR, first.langKey)
                    .bind(VERSION_ATTR, first.version)
                    .fetch()
                    .awaitRowsUpdated()
                    .right()
            } catch (e: Throwable) {
                e.left()
            }


            suspend fun ApplicationContext.findOneUserByEmail(
                email: String
            ): Either&amp;lt;Throwable, User&amp;gt; = try {
                getBean&amp;lt;DatabaseClient&amp;gt;()
                    .sql(&quot;SELECT * FROM `user` WHERE LOWER(email) = LOWER(:email)&quot;)
                    .bind(&quot;email&quot;, email)
                    .fetch()
                    .awaitOne()
                    .let { row -&amp;gt;
                        User(
                            id = row[ID_ATTR] as UUID?,
                            login = row[LOGIN_ATTR] as String,
                            password = row[PASSWORD_ATTR] as String,
                            email = row[EMAIL_ATTR] as String,
                            langKey = row[LANG_KEY_ATTR] as String,
                            version = row[VERSION_ATTR] as Long
                        )
                    }.right()
            } catch (e: Throwable) {
                e.left()
            }
        }
    }

    /** Account REST API URIs */
    object UserRestApis {
        const val API_AUTHORITY = &quot;/api/authorities&quot;
        const val API_USERS = &quot;/api/users&quot;
        const val API_SIGNUP = &quot;/signup&quot;
        const val API_SIGNUP_PATH = &quot;$API_USERS$API_SIGNUP&quot;
        const val API_ACTIVATE = &quot;/activate&quot;
        const val API_ACTIVATE_PATH = &quot;$API_USERS$API_ACTIVATE?key=&quot;
        const val API_ACTIVATE_PARAM = &quot;{activationKey}&quot;
        const val API_ACTIVATE_KEY = &quot;key&quot;
        const val API_RESET_INIT = &quot;/reset-password/init&quot;
        const val API_RESET_FINISH = &quot;/reset-password/finish&quot;
        const val API_CHANGE = &quot;/change-password&quot;
        const val API_CHANGE_PATH = &quot;$API_USERS$API_CHANGE&quot;
    }
}

// Abstract entity model with Generic ID, which can be of any type
abstract class EntityModel&amp;lt;T&amp;gt;(
    open val id: T? = null
) {
    companion object {
        const val ID_MEMBER = &quot;id&quot;
    }
}

// Generic extension function that allows the ID to be applied to any EntityModel type
inline fun &amp;lt;reified T : EntityModel&amp;lt;ID&amp;gt;, ID&amp;gt; T.withId(id: ID): T {
    // Use reflection to create a copy with the passed ID
    return this::class.constructors.first { it.parameters.any { param -&amp;gt; param.name == ID_MEMBER } }
        .call(id, *this::class.constructors.first().parameters.drop(1).map { param -&amp;gt;
            this::class.members.first { member -&amp;gt; member.name == param.name }.call(this)
        }.toTypedArray())
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_die_verschiedenen_ansätze&quot;&gt;Die verschiedenen Ansätze&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_der_klassische_ansatz_mit_when&quot;&gt;Der klassische Ansatz mit `when&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val user: User by lazy { userFactory(USER) }

val result: Either&amp;lt;Throwable, User&amp;gt; = context.findOneUserByEmail(user.email)

when (result) {
    is Either.Left -&amp;gt; {
        val error = result.value
        println(&quot;Erreur : ${error.message}&quot;)
    }
    is Either.Right -&amp;gt; {
        val user = result.value
        println(&quot;Utilisateur trouvé : ${user.login}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Diese Methode, obwohl einfach und lesbar, nutzt die funktionalen Fähigkeiten von Arrow nicht vollständig aus.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_verwendung_von_fold_für_einen_präziseren_ansatz&quot;&gt;Verwendung von &lt;code&gt;fold&lt;/code&gt; für einen präziseren Ansatz&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;result.fold(
{ error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) },
{ user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`fold`ermöglicht es, Aktionen für die beiden Fälle (Left und Right) kurz und elegant zu definieren.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_transformation_mit_map_und_mapleft&quot;&gt;Transformation mit &lt;code&gt;map&lt;/code&gt; und `mapLeft&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val processedResult = result
    .map { user -&amp;gt; &quot;Utilisateur trouvé : ${user.login}&quot; }
    .mapLeft { error -&amp;gt; &quot;Erreur : ${error.message}&quot; }

println(processedResult.merge())&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dieser Ansatz ermöglicht es, die in Either enthaltenen Werte zu transformieren, während seine Struktur erhalten bleibt, ideal für komplexere Verarbeitungsketten.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_fehlerbehandlung_mit_getorelse&quot;&gt;Fehlerbehandlung mit `getOrElse&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val user = result.getOrElse { error -&amp;gt;
    println(&quot;Erreur : ${error.message}&quot;)
    User(login = &quot;default&quot;, email = &quot;default@example.com&quot;) // utilisateur par défaut
}
println(&quot;Login : ${user.login}&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`getOrElse`bietet eine elegante Fehlerbehandlung, indem es die Angabe eines Standardwertes erlaubt.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_seitliche_aktionen_mit_onleft_und_onright&quot;&gt;Seitliche Aktionen mit &lt;code&gt;onLeft&lt;/code&gt; und `onRight&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;result.onLeft { error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) }
.onRight { user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Diese Methoden ermöglichen das Ausführen von Aktionen auf jeder Seite ohne das Either zu ändern, perfekt für das Logging oder leichte Seiteneffekte.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_verkettung_von_operationen_mit_flatmap&quot;&gt;Verkettung von Operationen mit `flatMap&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;fun findUser(email: String): Either&amp;lt;Throwable, User&amp;gt; = // ... implémentation

fun getUserPermissions(user: User): Either&amp;lt;Throwable, List&amp;lt;String&amp;gt;&amp;gt; = // ... implémentation

val userPermissions = findUser(&quot;user@example.com&quot;)
    .flatMap { user -&amp;gt; getUserPermissions(user) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;flatMap`ist nützlich, um Vorgänge zu verketten, die einige zurückgeben`Either&lt;/code&gt;, dadurch vermeidend die`Either`verschachtelt.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_bidirektionale_transformation_mit_bimap&quot;&gt;Bidirektionale Transformation mit `bimap&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val result: Either&amp;lt;Throwable, User&amp;gt; = // ... obtention du résultat
val processedResult = result.bimap(
    { error -&amp;gt; &quot;Erreur: ${error.message}&quot; },
    { user -&amp;gt; &quot;Utilisateur: ${user.login}&quot; }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`bimap`ermöglicht es, sowohl die linke als auch die rechte Seite in einem Vorgang zu transformieren.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_umkehrung_der_seiten_mit_swap&quot;&gt;Umkehrung der Seiten mit `swap&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val result: Either&amp;lt;Throwable, User&amp;gt; = // ... obtention du résultat
val swapped = result.swap()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;swap`ist nützlich, wenn du die Seiten eines umkehren möchtest`Either&lt;/code&gt;, zum Beispiel um die Schnittstelle einer Funktion an eine andere anzupassen.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_verwendung_von_tap_und_tapleft&quot;&gt;Verwendung von &lt;code&gt;tap&lt;/code&gt; und &lt;code&gt;tapLeft&lt;/code&gt; :&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;result.tap { user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }
.tapLeft { error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ähnlich zu`onLeft` et &lt;code&gt;onRight&lt;/code&gt;, aber diese Methoden geben das ursprüngliche Either zurück, was nützlich ist, um Operationen zu ketten.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_verwendung_von_recover&quot;&gt;Verwendung von &lt;code&gt;recover&lt;/code&gt; :&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;val recoveredUser = result.recover { error -&amp;gt;
    println(&quot;Erreur récupérée : ${error.message}&quot;)
    User(login = &quot;recovered&quot;, email = &quot;recovered@example.com&quot;)
}
println(&quot;Login : ${recoveredUser.login}&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Diese Methode ermöglicht das Umwandeln eines Either.Left in ein Either.Right, indem sie einen Ersatzwert bereitstellt.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_praktische_anwendungsfälle&quot;&gt;Praktische Anwendungsfälle&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Benutzen Sie`fold`für einfache Vorgänge, die eine Bearbeitung pro Fall erfordern. - Bevorzugen Sie`map` et &lt;code&gt;mapLeft`für Datenumwandlungen ohne die Struktur des`Either&lt;/code&gt;. - Wählen Sie für`flatMap`beim Verketten von Operationen, die fehlschlagen können - Verwenden Sie`recover`um einen Standardwert im Fehlerfall bereitzustellen - Wählen`onLeft` et &lt;code&gt;onRight&lt;/code&gt; (ou &lt;code&gt;tap&lt;/code&gt; et &lt;code&gt;tapLeft&lt;/code&gt;) für Nebenwirkungen wie das Logging. - Verwenden Sie`bimap`um beide Seiten in eine einzige Operation zu verwandeln. - Anwenden`swap`wenn Sie die Schnittstelle einer Funktion an eine andere anpassen müssen.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_fazit&quot;&gt;Fazit&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Jede dieser Ansätze hat je nach Nutzungskontext ihre Vorteile. Methoden wie`fold`, &lt;code&gt;map&lt;/code&gt;/&lt;code&gt;mapLeft&lt;/code&gt;, et `recover`sind besonders nützlich, wenn Sie mehrere Operationen hintereinander ausführen oder Daten funktional transformieren möchten.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Die Monade`Either`Arrow bietet eine bemerkenswerte Flexibilität für die Handhabung von Erfolgs- und Fehlerfällen in Ihren Kotlin-Anwendungen. Wenn Sie diese verschiedenen Ansätze beherrschen, können Sie robuster, lesbarer und funktionaleren Code schreiben.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;In Ihrem nächsten Projekt zögern Sie nicht, diese Techniken zu erkunden, um das Beste aus der funktionalen Programmierung mit Kotlin und Arrow herauszuholen!&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_weitergehen&quot;&gt;Weitergehen&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Offizielle Dokumentation von Arrow:https://arrow-kt.io/docs/apidocs/arrow-core/arrow.core/-either/[Pfeil entweder] - Kotlin Coroutines mit Arrow :https://arrow-kt.io/docs/fx/[Arrow Fx Coroutines]&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Vergiss nicht, deine Erfahrungen und deine bevorzugten Techniken zum Arbeiten damit zu teilen.`Either`in den Kommentaren unten!&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_einleitung&quot;&gt;Einleitung&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_verwendung_des_befehls_find&quot;&gt;Verwendung des Befehls `find&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_zusätzliche_optionen_für_find&quot;&gt;Zusätzliche Optionen für `find&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_verwendung_des_befehls_locate&quot;&gt;Verwendung des Befehls `locate&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_verwendung_des_befehls_grep_zum_suchen_von_text_in_dateien&quot;&gt;Verwendung des Befehls &lt;code&gt;grep&lt;/code&gt; zum Suchen von Text in Dateien&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_fazit&quot;&gt;Fazit&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_einleitung&quot;&gt;Einleitung&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Die Problematik: Dateien in einem Linux-Betriebssystem über das Terminal suchen.&lt;/div&gt;
&lt;p&gt;In diesem Artikel werden wir untersuchen, wie man unter Ubuntu mithilfe eines Zsh-Terminals nach einer Datei sucht. Zsh (Z shell) ist ein leistungsfähiger und weit verbreiteter Shell-Interpreter, der aufgrund seiner Flexibilität und seiner erweiterten Funktionen häufig verwendet wird.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ubuntu, eine beliebte Linux-Distribution, bietet mehrere Kommandozeilen-Tools zum Suchen von Dateien. Wir werden sehen, wie man Befehle wie`find`, &lt;code&gt;locate&lt;/code&gt; et `grep`Um Dateien im Terminal schnell und effizient zu finden.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_verwendung_des_befehls_find&quot;&gt;Verwendung des Befehls `find&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Die Bestellung`find`ermöglicht das Suchen nach Dateien in einem bestimmten Verzeichnis und seinen Unterverzeichnissen. Die Grundsyntax lautet wie folgt:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;find [chemin] -name [nom_du_fichier]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hier ist ein praktisches Beispiel, in dem wir nach einer Datei namens suchen.&lt;code&gt;example.txt`im Verzeichnis&lt;/code&gt;/home`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;find /home -name &quot;example.txt&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dieser Befehl wird alle Unterverzeichnisse von`/home`und den vollständigen Pfad der Datei anzeigen, wenn sie gefunden wird.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Online-Handbuch des Befehls`find`:https://man.archlinux.org/man/find.1.fr/[man find,windows=read-later]&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_zusätzliche_optionen_für_find&quot;&gt;Zusätzliche Optionen für `find&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Der Befehl`find`ist sehr mächtig und verfügt über viele Optionen. Hier sind einige nützliche Beispiele:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Nach Dateityp suchen&lt;/strong&gt;: Um nur nach Dateien zu suchen, verwenden Sie`-type f`, und um Verzeichnisse zu suchen, verwenden`-type d`. - &lt;strong&gt;Nach Größe suchen&lt;/strong&gt;: Sie können auch die Dateien nach ihrer Größe filtern, indem Sie die Option verwenden`-size`. Par exemple, pour rechercher des fichiers de plus de 100 Mo, utilisez :&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;find /home -size +100M&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_verwendung_des_befehls_locate&quot;&gt;Verwendung des Befehls `locate&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Der Befehl`locate`ist schneller als`find`weil sie eine vorindizierte Datenbank der auf dem System vorhandenen Dateien verwendet. Sie müssen diese Datenbank zunächst mit dem folgenden Befehl aktualisieren:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;sudo updatedb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Danach können Sie eine Datei wie folgt suchen:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;locate example.txt&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ich verwendehttps://fr.wikipedia.org/wiki/Z_Shell[zsh]mithttps://github.com/ohmyzsh/ohmyzsh/wiki[oh-my-zsh], es stellt sich heraus, dass die Bestellung`locate`ist nicht zugänglich seit`zsh`aber durchaus möglich seit`bash`, um diesem entgegenzuwirken, das Argument`-c`der Bestellung`bash`ermöglicht das Ausführen eines Befehls`bash`von einem anderen Typ Terminal aus.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;hier suche ich die Dateien die mit dem Muster enden`001.pdf`im Benutzerverzeichnis&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;bash -c &quot;locate ~/*001.pdf&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Online-Handbuch des Befehls`locate` : &lt;a href=&quot;https://man.archlinux.org/man/locate.1.fr/&quot;&gt;man locate&lt;/a&gt;*&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_verwendung_des_befehls_grep_zum_suchen_von_text_in_dateien&quot;&gt;Verwendung des Befehls &lt;code&gt;grep&lt;/code&gt; zum Suchen von Text in Dateien&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Wenn Sie nach einem bestimmten Text innerhalb einer Datei suchen möchten, können Sie verwenden`grep`. Zum Beispiel, um das Vorkommen des Wortes &quot;Ubuntu&quot; in allen Dateien zu suchen`.txt`Aus dem aktuellen Verzeichnis, verwenden Sie :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;grep &quot;Ubuntu&quot; *.txt&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_fazit&quot;&gt;Fazit&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Die Suche nach Dateien unter Ubuntu mit einem Zsh-Terminal kann mithilfe mehrerer leistungsstarker Tools erfolgen.`find`ist flexibel und bietet eine Vielzahl von Optionen, während`locate`Ermöglicht eine schnelle Suche mithilfe einer vorbereiteten Datenbank. Schließlich,`grep`ermöglicht das Finden von Textvorkommen innerhalb der Dateien.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Diese Befehle bieten dir eine vollständige Palette an Werkzeugen, um deine Dateisuche effizienter und an deine Bedürfnisse angepasst zu machen, und jedes dieser Befehle verfügt über ein Handbuch, das mit dem Befehl sichtbar ist.&lt;code&gt;man&lt;/code&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_die_tastatur&quot;&gt;Die Tastatur :&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_die_taste_ctrl&quot;&gt;&lt;em&gt;die Taste &amp;lt;Ctrl&amp;gt;&lt;/em&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_erlaubnisautorisierung&quot;&gt;Erlaubnis(Autorisierung)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_dateisuche&quot;&gt;Dateisuche&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_die_tastatur&quot;&gt;Die Tastatur :&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_die_taste_ctrl&quot;&gt;&lt;em&gt;die Taste &amp;lt;Ctrl&amp;gt;&lt;/em&gt;&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://korben.info/les-raccourcis-clavier-pour-bash-terminal-linux-et-macos.html&quot;&gt;Link&lt;/a&gt;&lt;br&gt;
&lt;a href=&quot;https://blogmotion.fr/systeme/astuces-bash-linux-16175&quot;&gt;anderer Link&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_erlaubnisautorisierung&quot;&gt;Erlaubnis(Autorisierung)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;CHMOD wird verwendet, um die Berechtigungen einer Datei zu ändern.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Erlaubnis      Befehl&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U   G   W rwx rwx rwx     chmod 777 filename rwx rwx r-x     chmod 775 filename rwx r-x r-x     chmod 755 filename rw- rw- r--     chmod 664 filename rw- r-- r--     chmod 644 filename&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U = User G = Gruppe W = Welt&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;r = lesbar w = beschreibbar x = ausführbar - = keine Berechtigung&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Eine andere Möglichkeit, die Berechtigungen zu sehen:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;400 lesbar durch den Eigentümer 040     von der Gruppe gelesen 004     von jemandem gelesen (anderes) 200     geschrieben vom Eigentümer 020     nach Gruppe schreiben 002     von irgendjemand geschrieben 100     vom Eigentümer ausführen Ausführen nach Gruppe von jedem ausführbar&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Um eine Kombination zu erhalten, reicht es, sie zu addieren.&lt;br&gt;
Zum Beispiel, um vom Eigentümer gelesen, geschrieben, ausgeführt zu werden,&lt;br&gt;
gelesen, ausgeführt, von einer Gruppe und ausgeführt von irgendjemand,&lt;br&gt;
Sie würden 400+200+100+040+010+001 addieren, um 751 zu erhalten.&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_dateisuche&quot;&gt;&lt;a href=&quot;/blog/2024/0074_seach_file_linux_post.html&quot;&gt;Dateisuche&lt;/a&gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;

&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Lesezeit : 3 min&lt;/em&gt; Pandoc ein universeller Dokumentkonverter&lt;/div&gt;
&lt;p&gt;Pandoc ist eine Open-Source-Textverarbeitungssoftware, die verwendet werden kann, um Dokumente zwischen verschiedenen Formaten zu konvertieren. Es gibt mehrere Möglichkeiten, Pandoc zu installieren.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_installation_von_der_download_seite&quot;&gt;&lt;strong&gt;Installation von der Download-Seite&lt;/strong&gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Um Pandoc von der Download-Seite zu installieren, gehen Sie wie folgt vor:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Greife auf die Pandoc-Download-Seite zu :https://pandoc.org/installing.html/[&lt;a href=&quot;https://pandoc.org/installing.html&quot; class=&quot;bare&quot;&gt;https://pandoc.org/installing.html&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Lade den Paket-Installer für dein Betriebssystem herunter.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Führen Sie das Installationsprogramm aus, um Pandoc zu installieren.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Installation aus einer ZIP-Datei&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Um Pandoc aus einer Zip-Datei zu installieren, gehen Sie wie folgt vor:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Laden Sie die ZIP-Datei herunter, die die Pandoc-Binaries und die Dokumentation enthält.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Entpacken Sie die ZIP-Datei.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Verschieben Sie die Binaries in ein Verzeichnis Ihrer Wahl.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Installation mit Chocolatey&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Um Pandoc mithilfe von Chocolatey zu installieren, gehen Sie wie folgt vor:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Öffnen Sie eine Eingabeaufforderung.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Führen Sie den folgenden Befehl aus:&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-powershell&quot; data-lang=&quot;powershell&quot;&gt;choco install pandoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Installation mit winget&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Um Pandoc mit winget zu installieren, gehen Sie wie folgt vor:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Öffnen Sie eine Eingabeaufforderung.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Führen Sie den folgenden Befehl aus:&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-powershell&quot; data-lang=&quot;powershell&quot;&gt;winget install --source winget --exact --id JohnMacFarlane.Pandoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Empfehlungen&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Standardmäßig erstellt Pandoc PDFs mit LaTeX. Es wird empfohlen, LaTeX über MiKTeX zu installieren. Mit der Option`--pdf-engine`, Sie können jedoch andere Programme für diese Aufgabe angeben.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Warnung&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Die Verwendung mehrerer Installationsmethoden kann zu zwei unterschiedlichen Installationen von Pandoc führen. Es wird empfohlen, Pandoc ordnungsgemäß zu deinstallieren, bevor Sie zu einer alternativen Installationsmethode wechseln.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Installation unter Linux über WSL&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Überprüfen Sie, ob die Version von pandoc in Ihrem Paketmanager nicht veraltet ist. Pandoc befindet sich in den Repositorys von Debian, Ubuntu, Slackware, Arch, Fedora, NixOS, openSUSE, Gentoo und Void.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Um die neueste Version zu erhalten, bieten wir ein binäres Paket für die Architektur amd64 auf der Download-Seite an.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Die ausführbare Datei ist statisch verlinkt und hat weder dynamische Abhängigkeiten noch Abhängigkeiten von externen Datendateien. Hinweis: Aufgrund der statischer Linkierung des Pandoc-Binaries dieses Pakets kann keine Lua-Filter verwendet werden, die externe in C geschriebene Lua-Module erfordern.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ein Tarball und ein DEB-Installer werden bereitgestellt. Um das deb zu installieren:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;sudo dpkg -i $DEB&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Beispiel zum Zeitpunkt des Schreibens:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;wget https://github.com/jgm/pandoc/releases/download/3.1.11.1/pandoc-3.1.11.1-1-amd64.deb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;sudo dpkg -i pandoc-3.1.11.1-1-amd64.deb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;où `$DEB`ist der Pfad zur heruntergeladenen .deb-Datei. Das wird die ausführbare Datei installieren`pandoc`und die Manpage.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Wenn Sie eine RPM-basierte Distribution verwenden, können Sie vielleicht das DEB-Paket von unserer Download-Seite mit alien installieren.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Auf jeder Distribution können Sie vom Tarball aus installieren`$DEST`(zum Beispiel,&lt;code&gt;/usr/local/&lt;/code&gt; ou &lt;code&gt;$HOME/.local&lt;/code&gt;) beim Machen:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;tar xvzf $TGZ --strip-components 1 -C $DEST&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;où `$TGZ`ist der Pfad zum heruntergeladenen gezippte Tarball. Für Pandoc-Versionen vor 2.0, die keinen Tarball bereitstellen, versuchen Sie stattdessen:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;ar p $DEB data.tar.gz | tar xvz --strip-components 2 -C $DEST&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sie können auch aus dem Quellcode installieren, indem Sie die nachfolgenden Anweisungen verwenden unter`Compilation à partir de la source`. Bitte beachten Sie, dass die meisten Distributionen die Haskell-Plattform in ihren Paket-Repositories haben. Zum Beispiel können Sie es unter Debian/Ubuntu installieren mit&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;apt-get install haskell-platform&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Standardmäßig erstellt Pandoc PDFs mit LaTeX. Wir empfehlen Ihnen, TeX Live über Ihren Paket-Manager zu installieren. (Auf Debian/Ubuntu,&lt;code&gt;apt-get install texlive&lt;/code&gt;). Mit der Option`--pdf-engine`, Sie können jedoch andere Programme für diese Aufgabe angeben.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Lesedauer : 2 min&lt;/em&gt; Eine vollständige Implementierung der Klasse kotlin.Triple in JavaScript, TypeScript und Python mittels funktionaler Programmierung erstellen.&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;Hinweis :&lt;/strong&gt;Die Typen`Maybe`, &lt;code&gt;Either&lt;/code&gt;, `Result`gehören nicht zur Grundsprache von JavaScript oder TypeScript, daher müssen wir sie selbst implementieren.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_javascript&quot;&gt;JavaScript&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-javascript&quot; data-lang=&quot;javascript&quot;&gt;//javascript
// Maybe type
const Maybe = (value) =&amp;gt; ({
  map: (fn) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? Maybe(fn(value)) : Maybe(null)),
  flatMap: (fn) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? fn(value) : Maybe(null)),
  getOrElse: (defaultValue) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? value : defaultValue),
});

// Either type
const Either = {
  Left: (value) =&amp;gt; ({
    map: (fn) =&amp;gt; Either.Left(value),
    flatMap: (fn) =&amp;gt; Either.Left(value),
    getOrElse: (defaultValue) =&amp;gt; defaultValue,
    isLeft: true,
    isRight: false,
  }),
  Right: (value) =&amp;gt; ({
    map: (fn) =&amp;gt; Either.Right(fn(value)),
    flatMap: (fn) =&amp;gt; fn(value),
    getOrElse: (defaultValue) =&amp;gt; value,
    isLeft: false,
    isRight: true,
  }),
};

// Triple class
class Triple {
  constructor(a, b, c) {
    this.a = a;
    this.b = b;
    this.c = c;
  }

  map(fn) {
    return new Triple(fn(this.a), fn(this.b), fn(this.c));
  }

  static of(a, b, c) {
    return new Triple(a, b, c);
  }

  // Example method using Maybe and Either
  divideBy(other) {
    return Maybe(this.b)
      .flatMap((numerator) =&amp;gt;
        Maybe(other)
          .flatMap((denominator) =&amp;gt;
            denominator !== 0
              ? Either.Right(numerator / denominator)
              : Either.Left(&#39;Division by zero&#39;)
          )
      )
      .getOrElse(Either.Left(&#39;Invalid input&#39;));
  }
}

// Example usage
const triple = Triple.of(1, 2, 3);
const result = triple.map((x) =&amp;gt; x * 2);
console.log(result); // Triple { a: 2, b: 4, c: 6 }

const divisionResult = triple.divideBy(2);
console.log(divisionResult); // Either.Right { value: 1 }

const invalidDivisionResult = triple.divideBy(0);
console.log(invalidDivisionResult); // Either.Left { value: &#39;Division by zero&#39; }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_typescript&quot;&gt;TypeScript&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;//Typescript
// Maybe type
// noinspection JSAnnotator

type Maybe&amp;lt;T&amp;gt; = {
  map&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U): Maybe&amp;lt;U&amp;gt;;
  flatMap&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;): Maybe&amp;lt;U&amp;gt;;
  getOrElse(defaultValue: T): T;
};

const just = &amp;lt;T&amp;gt;(value: T): Maybe&amp;lt;T&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U) =&amp;gt; just(fn(value)),
  flatMap: &amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;) =&amp;gt; fn(value),
  getOrElse: (_: T) =&amp;gt; value,
});

const nothing = &amp;lt;T&amp;gt;(): Maybe&amp;lt;T&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(_: (value: T) =&amp;gt; U) =&amp;gt; nothing&amp;lt;U&amp;gt;(),
  flatMap: &amp;lt;U&amp;gt;(_: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;) =&amp;gt; nothing&amp;lt;U&amp;gt;(),
  getOrElse: (defaultValue: T) =&amp;gt; defaultValue,
});

// Either type
type Either&amp;lt;L, R&amp;gt; = {
  map&amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; U): Either&amp;lt;L, U&amp;gt;;
  flatMap&amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;): Either&amp;lt;L, U&amp;gt;;
  getOrElse(defaultValue: R): R;
  isLeft: boolean;
  isRight: boolean;
};

const left = &amp;lt;L, R&amp;gt;(value: L): Either&amp;lt;L, R&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(_: (value: R) =&amp;gt; U) =&amp;gt; left&amp;lt;L, U&amp;gt;(value),
  flatMap: &amp;lt;U&amp;gt;(_: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;) =&amp;gt; left&amp;lt;L, U&amp;gt;(value),
  getOrElse: (defaultValue: R) =&amp;gt; defaultValue,
  isLeft: true,
  isRight: false,
});

const right = &amp;lt;L, R&amp;gt;(value: R): Either&amp;lt;L, R&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; U) =&amp;gt; right&amp;lt;L, U&amp;gt;(fn(value)),
  flatMap: &amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;) =&amp;gt; fn(value),
  getOrElse: (_: R) =&amp;gt; value,
  isLeft: false,
  isRight: true,
});

// Triple class
class Triple&amp;lt;T&amp;gt; {
  constructor(public a: T, public b: T, public c: T) {}

  map&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U): Triple&amp;lt;U&amp;gt; {
    return new Triple&amp;lt;U&amp;gt;(fn(this.a), fn(this.b), fn(this.c));
  }

  static of&amp;lt;T&amp;gt;(a: T, b: T, c: T): Triple&amp;lt;T&amp;gt; {
    return new Triple&amp;lt;T&amp;gt;(a, b, c);
  }

  // Example method using Maybe and Either
  divideBy(other: T): Either&amp;lt;string, number&amp;gt; {
    return just(this.b)
      .flatMap((numerator) =&amp;gt;
        just(other)
          .flatMap((denominator) =&amp;gt;
            denominator !== 0 ? right(numerator / denominator) : left(&#39;Division by zero&#39;)
          )
      )
      .getOrElse(left(&#39;Invalid input&#39;));
  }
}

// Example usage
const triple = Triple.of(1, 2, 3);
const result = triple.map((x) =&amp;gt; x * 2);
console.log(result); // Triple { a: 2, b: 4, c: 6 }

const divisionResult = triple.divideBy(2);
console.log(divisionResult); // Either.Right { value: 1 }

const invalidDivisionResult = triple.divideBy(0);
console.log(invalidDivisionResult); // Either.Left { value: &#39;Division by zero&#39; }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_python_pydantic_pymonad&quot;&gt;Python, pydantic, pymonad&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Um eine Implementierung in Python zu erstellen, indem man`pydantic`pour die Validierung der Typen und`pymonad`für die Monaden:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Abhängigkeiten installieren :&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;pip install pydantic pymonad&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-python&quot; data-lang=&quot;python&quot;&gt;from pymonad.either import Either, Left, Right
from pydantic import BaseModel, ValidationError, validator

# Définition de la classe Triple avec Pydantic
class Triple(BaseModel):
    a: int
    b: int
    c: int

    @validator(&#39;b&#39;)
    def validate_b(cls, b, values):
        if b == 0:
            raise ValueError(&#39;Division by zero is not allowed&#39;)
        return b

    # Méthode utilisant Either pour la gestion des erreurs
    def divide_by(self, other):
        def division(numerator, denominator):
            return Right(numerator / denominator)

        def handle_error(error):
            return Left(str(error))

        return Either(lambda: division(self.b, other)).or_else(handle_error)

# Exemple d&#39;utilisation
try:
    triple = Triple(a=1, b=2, c=3)
    result = triple.divide_by(2)

    if result.is_right:
        print(f&#39;Division result: {result.value}&#39;)
    else:
        print(f&#39;Error: {result.value}&#39;)

except ValidationError as e:
    print(f&#39;Validation Error: {e}&#39;)
except Exception as e:
    print(f&#39;An unexpected error occurred: {e}&#39;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;In diesem Beispiel:&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;pydantic`um die Klasse zu definieren`Triple`mit typisierten Feldern. Die Methode`divide_by`verwendet die Monade`Either&lt;/code&gt; de `pymonad`Um potenzielle Fehler aufgrund der Division durch Null zu behandeln. Personalisierte Validierung, um sicherzustellen, dass der Wert von`b`ist nicht gleich null. Wenn sie gleich null ist, wird eine Ausnahme ausgelöst, und`pymonad`Diese Ausnahme auffangen, um ein Ergebnis zurückzugeben`Left`den Fehler anzeigend.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_inhaltsverzeichnis&quot;&gt;Inhaltsverzeichnis&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
