&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Mein Videoplayer auf meinem Fernseher hat seine Art zu vorbeizugehen&lt;br&gt;
von einer Datei zur anderen beim fortlaufenden Lesen&lt;br&gt;
und sein Wiedergabemodus besteht darin, von 1&amp;#8230;&amp;#8203;..mp4 zu 10&amp;#8230;&amp;#8203;.mp4 zu wechseln,&lt;br&gt;
und nicht von 1&amp;#8230;&amp;#8203;mp4 bis 2&amp;#8230;&amp;#8203;.mp4.&lt;br&gt;
Das Problem ist, dass es fast 900 Dateien und Ordner gibt.&lt;br&gt;
Bingo, ein super Anwendungsfall von Groovy zum Manipulieren&lt;br&gt;
Dateien, Umbenennung, Suche nach einem Muster im Dateinamen&lt;br&gt;
oder Ordner.&lt;br&gt;
Hier ist das Ziel, die Namen zu ändern, die mit&lt;br&gt;
eine Zahl und dessen zweites Zeichen des Namens&lt;br&gt;
Ist keine Zahl, ich werde diesem Namen eine 0 am Anfang hinzufügen&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;renameFilesToStartWithTwoDigit.groovy&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-groovy&quot; data-lang=&quot;groovy&quot;&gt;#!/usr/bin/env groovy
/**
 * get a crossplateform separator
 * @return
 */
static String getSeparator() {
    System.getProperty(&quot;file.separator&quot;)
}
/**
 * rename file
 * @param file
 * @param newName
 * @return the renamed file
 */
static File rename(File file, String newName) {
    assert file.renameTo(file
            .parentFile.path +
            getSeparator() +
            newName)
    new File(file
            .parentFile.path +
            getSeparator() +
            newName)
}

String rootFolderPath = System.getProperty(&quot;user.home&quot;) +
        &quot;/Bureau/ng-courses/Udemy - Angular 7 &quot; +
        &quot;(formerly Angular 2) - The Complete Guide&quot;

File rootFolder = new File(rootFolderPath)
assert rootFolder.exists()
assert rootFolder.directory
assert rootFolder.canRead()

List&amp;lt;File&amp;gt; dirList = new ArrayList&amp;lt;&amp;gt;()

//Adding rootFolder in dirList
// just in case there is some files in it
dirList.add(rootFolder)

//looping to get list of directories
//recursively inside rootFolder
rootFolder.traverse { File file -&amp;gt;
    !file.directory ?: dirList.add(file)
}

//looping through dirList
//to rename directories filling criterias
for (int i = dirList.size() - 1; i &amp;gt;= 0; i--) {
    Character[] chars = dirList.get(i).name.chars
    !(chars[0].digit &amp;amp;&amp;amp; !chars[1].digit) ?:
            dirList.set(i, rename(dirList.get(i),
                    &quot;0${dirList.get(i).name}&quot;))
    if (dirList.get(i).directory) {
        //looping through directory
        //to rename file filling criterias
        dirList.get(i).listFiles().each { File f -&amp;gt;
            Character[] cs = f.name.chars
            !(cs[0].digit &amp;amp;&amp;amp; !cs[1].digit) ?:
                    rename(f, &quot;0${f.name}&quot;)
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Der Zweck dieses Skripts besteht darin, Dateien zu suchen,&lt;br&gt;
Aus einem übergeordneten Verzeichnis; Auswahl abrufen&lt;br&gt;
in einer Liste. Schließlich diese Liste von Dateien kopieren&lt;br&gt;
in einem Zielverzeichnis dies in Groovy.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;findCopyTo.groovy&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-groovy&quot; data-lang=&quot;groovy&quot;&gt;#!/usr/bin/env groovy
@Grab(&quot;commons-io:commons-io:2.6&quot;)

import groovy.io.FileType
import org.apache.commons.io.FileUtils

/**
 * un separateur OS independant
 * @return
 */
static String getSep() {
    System.getProperty(&quot;file.separator&quot;)
}
/**
 * la liste des fichiers dont le titre contient un item
 * de la liste des motifs
 *
 * @param path
 * @param motifs
 * @return la liste des chemins complet de fichiers
 */
static List&amp;lt;String&amp;gt; findFilesContainingMotifs(
        String path,
        List&amp;lt;String&amp;gt; motifs) {
    List&amp;lt;String&amp;gt; filePathResultList = new ArrayList&amp;lt;&amp;gt;()
    new File(path)
            .eachFileRecurse(FileType.FILES) {
                if (it.name.toLowerCase().contains(&#39;cucumber&#39;)) {
                    filePathResultList.add it.path
                }
            }
    filePathResultList
}

/**
 * copy vers la liste des fichiers
 * @param files
 * @param to
 */
static void copyFilesTo(List&amp;lt;String&amp;gt; files, String to) {
    File toDirDest = new File(to)
    files.each { String filepath -&amp;gt;
        File file = new File(filepath)
        //si le dernier caractere de to n&#39;est pas un separateur
        // alors ajoute le a la chaine
        (to.substring(to.length() - 1) == sep) ?: to.concat(sep)
        if (to + file.name != filepath) {
            FileUtils.copyFileToDirectory(file, toDirDest)
            file.delete()
        }
    }
}
/**
 * la list des arguments
 */
String userName = System.getProperty(&quot;user.name&quot;)
List&amp;lt;String&amp;gt; motifs = [&#39;cucumber&#39;]
String path = &quot;/media/$userName/320/Books/&quot;
String to = &quot;/media/$userName/320/Books/bdd/&quot;
/**
 * lappel aux methodes
 */
copyFilesTo(findFilesContainingMotifs(path, motifs), to)

//affiche moi les fichiers déplacés
findFilesContainingMotifs(path, motifs).each {
    println it
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hier werde ich mich mit dem Laden einer Eigenschaft in einem Build‑Projekt beschäftigen.https://docs.gradle.org/current/userguide/userguide.html[gradle]&lt;br&gt;
ohne dass sie im Code verfügbar ist.&lt;br&gt;
Die Eigenschaft wird in der Datei gradle.properties im Ordner ~/.gradle/gradle.properties definiert.&lt;br&gt;
~ ist eine Abkürzung der symbolischen Variable HOME_PATH, die den Benutzersitzungsstamm darstellt: derhttps://fr.wikipedia.org/wiki/R%C3%A9pertoire_personnel[persönliches Verzeichnis].&lt;br&gt;
Auf die gleiche Weise in einem Build-Projekthttps://maven.apache.org/guides/index.html[maven], mit ~/.m2/settings.xml Der Zweck dieses Skripts ist es, die Dateien zu löschen, die den angegebenen Mustern entsprechen.&lt;br&gt;
in der Variablen strCriteria. Dafür werde ich diehttps://fr.wikipedia.org/wiki/Fermeture_(informatique)[Abschlüsse]: jedes, findenAlle,  sammeln&lt;br&gt;
sowie die Klasse StringTokenizer, die meine Kriterien-Zeichenkette in Stücke zerlegt&lt;br&gt;
um eine Liste von Strings abzurufen Wenn eine der Dateien in meinem zu reinigenden Ordner eines der Muster im Namen enthält&lt;br&gt;
Dann wird er ein Kandidat für die Zerstörung sein, indem er zur Ergebnis-Liste hinzugefügt wird.&lt;br&gt;
Und in der letzten Zeile ein kleines Beispiel vonhttps://en.wikipedia.org/wiki/Elvis_operator[Elvis-Operator]&lt;br&gt;
filemanip.groovy&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-groovy&quot; data-lang=&quot;groovy&quot;&gt;#!/usr/bin/env groovy
//Mes criteres de selection des fichiers à detruire
String strCriteria = &quot;Dummies Dummie ajax Objective-C Windows blackberry &quot; +
        &quot;wordpress joomla ios c# f# rails ruby flex asp flash Dreamweaver adobe &quot; +
        &quot;CoffeeScript c++ .chm .epub .rar .zip .tar drupal drupals .net php javascript &quot; +
        &quot;.js iphone ipad js _js facebook gwt vaadin linq python py zope window &quot; +
        &quot;3D scala gaming active_directory tomcat jboss glassfish microsoft 2d &quot; +
        &quot;lego blogger blog cocoa dojo dom dotnetnuke eclipse .gz unity sharepoint &quot; +
        &quot;.tgz iwork filemaker .doc .txt&quot;


//repertoire personnel
String userDir = System.getProperty(&quot;user.home&quot;)
//un separateur de chemin crossplatform
String sep = System.getProperty(&quot;file.separator&quot;)
//la variable symbolique
String sym_books_vrac_path = &quot;books_vrac_path&quot;

//le chemin de mon fichier gradle.properties hors projet
String propertiesFilePath = userDir
        .concat(&quot;${sep}.gradle${sep}gradle.properties&quot;)


File propertiesFile = new File(propertiesFilePath)


//je m&#39;aassure que le fichier existe et que ce n&#39;est pas un dossier
assert propertiesFile.exists() &amp;amp;&amp;amp; !propertiesFile.directory

Properties gradleProperties = new Properties()

//on boucle avec un inpustream sur le fichier
//gradle.properties pour peupler ma variable gradleProperties
propertiesFile.withInputStream { InputStream it -&amp;gt;
    gradleProperties.load(it)
}

//le chemin du dossier books_vrac est la valeur de notre clé books_vrac_path
String pathVracDir = gradleProperties.get(sym_books_vrac_path)

//j&#39;ai récuperé tous ces livres en tapant cette commande dans le terminal
//wget -m -np -c -R &quot;index.html*&quot; &quot;http://the-eye.eu/public/Books/IT%20Various/&quot;

//on ouvre le dossier dont le chemin est dans la variable pathVracDir
// on s&#39;assure qu&#39;il existe et que c&#39;est un dossier
File vracDir = new File(pathVracDir)
assert vracDir.exists() &amp;amp;&amp;amp; vracDir.directory


//separer les élèments de ma liste de critère
StringTokenizer tokenizer = new StringTokenizer(strCriteria)

//la liste de critere
List&amp;lt;String&amp;gt; criteriaList = new ArrayList&amp;lt;&amp;gt;()

//j&#39;itère sur les tokens et je construit ma liste de token,
// mot clef critère de recherche
tokenizer.each { String it -&amp;gt;
    criteriaList.add(it.toLowerCase())
}

//je collect tous les noms de fichier dans le dossier
List&amp;lt;String&amp;gt; fileNameList = vracDir
        .listFiles()
        .collect { File it -&amp;gt;
            it.directory ?: it.name
        }

// je collect les noms de fichier qui contiendraient un des criteres
List&amp;lt;String&amp;gt; resultList = fileNameList.findAll { String name -&amp;gt;
    criteriaList.findAll { String crit -&amp;gt;
        name.toLowerCase().contains(crit)
    }
}

// je parcours ma liste de résultat pour les effacer
resultList.each { String fileName -&amp;gt;
    assert new File(vracDir.path + sep + fileName).delete()
}

println fileNameList.size()
println resultList.size()
resultList.empty ?: println(vracDir.path + sep + resultList.first())&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hier ist ein funktionierender Codeausschnitt in Groovy,&lt;br&gt;
um alle Vorkommen einer Zeichenfolge in einem String zu ändern&lt;br&gt;
&amp;lt;/think&amp;gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;und lade eine .properties-Datei in ein Properties-Objekt.&lt;br&gt;
Einen Befehl in einem String ausführen.&lt;br&gt;
replaceTextinFile.groovy&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-groovy&quot; data-lang=&quot;groovy&quot;&gt;#!/usr/bin/env groovy
println System.getProperty(&quot;user.home&quot;)

static String getSeparator_() {
    System.getProperty(&quot;file.separator&quot;)
}

String separator = separator_

String path = System.getProperty(&quot;user.home&quot;)
        .concat(&quot;${separator}.gradle&quot; +
                separator +
                &quot;gradle.properties&quot;)

File propertiesFile = new File(path)

assert propertiesFile.exists() &amp;amp;&amp;amp; !propertiesFile.directory

Properties gradleProperties = new Properties()

propertiesFile.withInputStream { InputStream it -&amp;gt;
    gradleProperties.load(it)
}

String user_name = gradleProperties.getProperty(&quot;user_name&quot;)

String text
String resultText
text = new File(&quot;${System.getProperty(&quot;user.home&quot;)}&quot; +
        separator +
        &quot;src&quot; +
        separator +
        &quot;cheroliv.github.io&quot; +
        separator +
        &quot;src&quot; +
        separator +
        &quot;main&quot; +
        separator +
        &quot;resources&quot; +
        separator +
        &quot;eco_space.txt&quot;).text

String to = separator +
        &quot;media&quot; +
        separator +
        &quot;${user_name}&quot; +
        separator +
        &quot;320&quot; +
        separator +
        &quot;videoCours&quot; +
        separator
String from = &quot;${System.getProperty(&quot;user.home&quot;)}&quot; +
        separator +
        &quot;p2p&quot; +
        separator

resultText = text.replace(to, from)

println resultText

//execute command line in a string
println &quot;rsync -avr ${resultText} ${to}&quot;.execute().text&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hier ist ein funktionierender Groovy-Code, der eine Textdatei erzeugt,&lt;br&gt;
avec les 256 premiers caractères lisibles du tableau ASCII&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-groovy&quot; data-lang=&quot;groovy&quot;&gt;#!/usr/bin/env groovy
import java.nio.charset.StandardCharsets

List&amp;lt;Character&amp;gt; chars = new ArrayList&amp;lt;&amp;gt;()
int j = 0
Character jumpLine = &#39;\n&#39;

256.times { Integer idx -&amp;gt;
    if (Character.isAlphabetic(idx) || Character.isDigit(idx)) {
        if (j % 10 == 0 &amp;amp;&amp;amp; j != 0) {
            chars.add(jumpLine)
            chars.add(idx as char)
        } else chars.add(idx as char)
        j++
    }
}

String seperator = System.getProperty(&quot;file.separator&quot;)

String path = &quot;${System.getProperty(&quot;user.home&quot;)}${seperator}ascii.txt&quot;
File speCharFile = new File(path)

if (speCharFile.exists() &amp;amp;&amp;amp; !speCharFile.directory) {
    speCharFile.text = &quot;&quot;
} else {
    speCharFile.createNewFile()
}

String text = new String()

chars.each { Character it -&amp;gt;
    text = it == jumpLine ? &quot;$text$it&quot; : &quot;$text $it &quot;
}

speCharFile.setText(text, StandardCharsets.UTF_8.toString())&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ich habe die Datei spe_char.groovy benannt,&lt;br&gt;
vom Ordner, in dem die Datei ist&lt;br&gt;
ein Terminal öffnen und kopieren und einfügen, um das Skript auszuführen&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
